import React from 'react'
import { Icon } from 'antd'
import PermissionCheckerV2 from '../../../../../components/permissionCheckerV2'
import FilterInput from '../../../../../components/tables/components/FilterInput'
import { COLORS } from '../../../../../constants/colors'
import Cookies from 'universal-cookie'
import moment from 'moment-timezone'
import { FilterSelectPartners, FilterDateRange } from '../../../../../components/tables/helperCells'

const cookies = new Cookies()

export function reconListTable ({
  handleDetailPage,
  searchTextQuery,
  handleInputChange,
  handleSearch,
  isFilterVisible,
  setIsFilterVisible,
  isChange,
  providerList,
  onSearchDate
}) {
  return [
    {
      key: 'recon_action',
      title: 'Action',
      dataIndex: 'recon_id',
      render: (val, record) => (
        <PermissionCheckerV2 requiredPermission='ops.view_agent_provider_list'>
          <i className='far fa-eye agent-config-btn' onClick={() => handleDetailPage(record.id)} />
        </PermissionCheckerV2>
      ),
      align: 'center'
    },
    {
      key: 'recon_name',
      title: 'Recon Name',
      dataIndex: 'recon_name',
      filterIcon: (
        <Icon
          type='search'
          style={{
            color: searchTextQuery.recon_name && COLORS.blue
          }}
        />
      ),
      filterDropdown: (
        <FilterInput
          idIdentifier='recon_name'
          className='agent-table-search'
          searchText={isChange ? searchTextQuery.recon_name : ''}
          onInputChange={e => handleInputChange(e, 'recon_name')}
          onSearch={e => handleSearch(e, 'recon_name')}
        />
      ),
      filterDropdownVisible: isFilterVisible === 'recon_name',
      onFilterDropdownVisibleChange: (visible) => setIsFilterVisible(visible ? 'recon_name' : searchTextQuery.recon_name)
    },
    {
      key: 'provider_name',
      title: 'Provider Name',
      dataIndex: 'provider',
      filterIcon: (
        <Icon
          type='search'
          style={{
            color: searchTextQuery.provider_name && COLORS.blue
          }}
        />
      ),
      filterDropdown: (
        <FilterSelectPartners
          idIdentifier='provider'
          searchText={isChange ? searchTextQuery.provider : ''}
          onInputChange={e => handleInputChange(e, 'provider')}
          onSearch={e => handleSearch(e, 'provider')}
          partners={providerList}
        />
      ),
      filterDropdownVisible: isFilterVisible === 'provider',
      onFilterDropdownVisibleChange: (visible) => setIsFilterVisible(visible ? 'provider' : searchTextQuery.provider)
    },
    {
      key: 'recon_purpose',
      title: 'Recon Purpose',
      dataIndex: 'recon_purpose',
      filterIcon: (
        <Icon
          type='search'
          style={{
            color: searchTextQuery.recon_purpose && '#1890ff'
          }}
        />
      ),
      filterDropdown: (
        <FilterSelectPartners
          idIdentifier='recon_purpose'
          searchText={isChange ? searchTextQuery.recon_purpose : ''}
          onInputChange={e => handleInputChange(e, 'recon_purpose')}
          onSearch={e => handleSearch(e, 'recon_purpose')}
          placeholder='Select Recon Purpose'
          partners={[{
            name: 'New',
            code: 'NEW'
          }, {
            name: 'Endorsement',
            code: 'ENDORSEMENT'
          }]}
        />
      ),
      filterDropdownVisible: isFilterVisible === 'recon_purpose',
      onFilterDropdownVisibleChange: (visible) => setIsFilterVisible(visible ? 'recon_purpose' : searchTextQuery.recon_purpose)
    },
    {
      key: 'recon_type',
      title: 'Recon Type',
      dataIndex: 'recon_type',
      filterIcon: (
        <Icon
          type='search'
          style={{
            color: searchTextQuery.recon_type && '#1890ff'
          }}
        />
      ),
      filterDropdown: (
        <FilterSelectPartners
          idIdentifier='recon_type'
          searchText={isChange ? searchTextQuery.recon_type : ''}
          onInputChange={e => handleInputChange(e, 'recon_type')}
          onSearch={e => handleSearch(e, 'recon_type')}
          placeholder='Select Recon Type'
          partners={[{
            name: 'Ojk Commission',
            code: 'OJK'
          }, {
            name: 'Extra Commission',
            code: 'EXTRA_COMMISSION'
          }]}
        />
      ),
      filterDropdownVisible: isFilterVisible === 'recon_type',
      onFilterDropdownVisibleChange: (visible) => setIsFilterVisible(visible ? 'recon_type' : searchTextQuery.recon_type)
    },
    {
      key: 'recon_to',
      title: 'Recon To',
      dataIndex: 'recon_to',
      filterIcon: (
        <Icon
          type='search'
          style={{
            color: searchTextQuery.recon_to && '#1890ff'
          }}
        />
      ),
      filterDropdown: (
        <FilterSelectPartners
          idIdentifier='recon_to'
          searchText={isChange ? searchTextQuery.recon_to : ''}
          onInputChange={e => handleInputChange(e, 'recon_to')}
          onSearch={e => handleSearch(e, 'recon_to')}
          placeholder='Select Recon To'
          partners={[{
            name: 'PPIB',
            code: 'PPIB'
          }, {
            name: 'Provider',
            code: 'PROVIDER'
          }]}
        />
      ),
      filterDropdownVisible: isFilterVisible === 'recon_to',
      onFilterDropdownVisibleChange: (visible) => setIsFilterVisible(visible ? 'recon_to' : searchTextQuery.recon_to)
    },
    {
      key: 'file_name',
      title: 'File Name',
      dataIndex: 'file_name',
      align: 'center'
    },
    {
      key: 'status',
      title: 'Status',
      dataIndex: 'status',
      filterIcon: (
        <Icon
          type='search'
          style={{
            color: searchTextQuery.status && '#1890ff'
          }}
        />
      ),
      filterDropdown: (
        <FilterSelectPartners
          idIdentifier='status'
          searchText={isChange ? searchTextQuery.status : ''}
          onInputChange={e => handleInputChange(e, 'status')}
          onSearch={e => handleSearch(e, 'status')}
          placeholder='Select Status'
          partners={[{
            name: 'Queued',
            code: 'QUEUED'
          }, {
            name: 'In Progress',
            code: 'IN_PROGRESS'
          },
          {
            name: 'Success',
            code: 'SUCCESS'
          },
          {
            name: 'Failed',
            code: 'FAILED'
          },
          {
            name: 'Partial',
            code: 'PARTIAL'
          }
          ]}
        />
      ),
      filterDropdownVisible: isFilterVisible === 'status',
      onFilterDropdownVisibleChange: (visible) => setIsFilterVisible(visible ? 'status' : searchTextQuery.status)
    },
    {
      key: 'error',
      title: 'Error',
      dataIndex: 'error',
      align: 'center'
    },
    {
      key: 'remarks',
      title: 'Remarks',
      dataIndex: 'remarks',
      align: 'center'
    },
    {
      key: 'created_at',
      title: 'Created At',
      dataIndex: 'created_at',
      align: 'center',
      render: (val, record) => {
        const userTimeZone = cookies.get('userProfile').user_timezone
        return moment(val).tz(userTimeZone).format('MMM DD,YYYY hh:mm A')
      },
      filterIcon: (
        <Icon
          type='search'
          style={{
            color: searchTextQuery.created_at_start && searchTextQuery.created_at_end && '#1890ff'
          }}
        />
      ),
      filterDropdown: (
        <FilterDateRange
          idIdentifier='CreatedAt'
          onInputChange={e => handleInputChange(e, 'created_at')}
          onSearch={(e) => onSearchDate(e, 'CreatedAt')}
        />
      ),
      filterDropdownVisible: isFilterVisible === 'created_at',
      onFilterDropdownVisibleChange: (visible) => setIsFilterVisible(visible ? 'created_at' : searchTextQuery.created_at_start)
    },
    {
      key: 'created_by',
      title: 'Created By',
      dataIndex: 'created_by',
      align: 'center',
      filterIcon: (
        <Icon
          type='search'
          style={{
            color: searchTextQuery.created_by && '#1890ff'
          }}
        />
      ),
      filterDropdown: (
        <FilterInput
          idIdentifier='created_by'
          className='agent-table-search'
          searchText={isChange ? searchTextQuery.created_by : ''}
          onInputChange={e => handleInputChange(e, 'created_by')}
          onSearch={e => handleSearch(e, 'created_by')}
        />
      ),
      filterDropdownVisible: isFilterVisible === 'created_by',
      onFilterDropdownVisibleChange: (visible) => setIsFilterVisible(visible ? 'created_by' : searchTextQuery.created_by)
    },
    {
      key: 'template_file',
      title: 'Template File',
      dataIndex: 'file_url',
      align: 'center'
    },
    {
      key: 'recon_status',
      title: 'Recon Status',
      dataIndex: 'recon_status',
      align: 'center'
    }
  ]
}

