import {
  addReconApi, editReconApi, getAgentReconListApi,
  getAgentReconPolicyListApi, getAgentReconDetailApi
} from '../../config/urls'

export const RECON_ACTIONS = {
  GET_RECON_LIST_REQUEST: 'GET_RECON_LIST_REQUEST',
  GET_RECON_LIST: 'GET_RECON_LIST',

  GET_RECON_DETAIL_REQUEST: 'GET_RECON_DETAIL_REQUEST',
  GET_RECON_DETAIL: 'GET_RECON_DETAIL',

  GET_POLICY_LIST_REQUEST: 'GET_POLICY_LIST_REQUEST',
  GET_POLICY_LIST: 'GET_POLICY_LIST',

  ADD_RECON_REQUEST: 'ADD_RECON_REQUEST',
  ADD_RECON: 'ADD_RECON'
}

export const getReconDetail = (payload) => ({
  type: RECON_ACTIONS.GET_RECON_DETAIL_REQUEST,
  payload: {
    ...payload,
    method: 'GET',
    url: getAgentReconDetailApi(payload.reconId)
  }
})

export const getReconList = (payload) => ({
  type: RECON_ACTIONS.GET_RECON_LIST_REQUEST,
  payload: {
    ...payload,
    method: 'GET',
    url: getAgentReconListApi
  }
})

export const getPolicyList = (payload) => ({
  type: RECON_ACTIONS.GET_POLICY_LIST_REQUEST,
  payload: {
    ...payload,
    method: 'GET',
    url: getAgentReconPolicyListApi(payload.reconId)
  }
})

export const addRecon = (payload) => ({
  type: RECON_ACTIONS.ADD_RECON_REQUEST,
  payload: {
    ...payload,
    method: payload.reconId ? 'PUT' : 'POST',
    url: payload.reconId ? editReconApi(payload.reconId) : addReconApi
  }
})
