import { RECON_ACTIONS } from './actions'

export const INITIAL_STATE = {}

const reducer = (state = INITIAL_STATE, action = {}) => {
  const { type, payload = {} } = action
  switch (type) {
    case RECON_ACTIONS.GET_RECON_LIST:
    case RECON_ACTIONS.GET_RECON_DETAIL:
    case RECON_ACTIONS.GET_POLICY_LIST:
    case RECON_ACTIONS.ADD_RECON:
      return {
        ...state,
        ...payload
      }
    default:
      return {
        ...(state || {})
      }
  }
}

export default reducer
