import { resetError, useErrorContextValue } from '@pasarpolis/common-react-hooks'
import { Button, Form, Row, Radio } from 'antd'
import { useCallback, useEffect, useState } from 'react'
import renderFormItemsUtil from '../../../../../../helpers/renderFormItems'
import { showNotification } from '../../../../../../components/ShowNotification'
import UploadImgPreview from '../../../components/UploadImgPreview'
import { useAddRecon } from '../../state/hooks/useReconState'
import { ReconFormStyle } from './index.style'
import PropTypes from 'prop-types'
import moment from 'moment-timezone'
import { useGetProviderList } from '../../../store/state/hooks/useAgentStore'
import { get, isEmpty } from 'lodash'

function ReconForm (props) {
  const { defaultValues } = props

  const [reconType, setReconType] = useState(get(defaultValues, 'recon_type', ''))
  const [reconTo, setReconTo] = useState(get(defaultValues, 'recon_to', ''))
  const [errorObj, setErrorObj] = useState({})

  const [reconFile, setReconFile] = useState(get(defaultValues, 'file_url', ''))
  const [invoiceFile, setInvoiceFile] = useState(get(defaultValues, 'invoice_url', ''))
  const [paymentProofFile, setPaymentProofFile] = useState(get(defaultValues, 'payment_proof_url', ''))
  const [, addReconRequest] = useAddRecon()

  const [{ getProviderListData = [] }, getProviderListRequest] = useGetProviderList()

  const [{ ADD_RECON_ERROR, addReconStatus, GET_PROVIDER_LIST_ERROR, getProviderListStatus }, dispatchError
  ] = useErrorContextValue()

  useEffect(() => {
    if (addReconStatus === 'success') {
      if (defaultValues) {
        showNotification('success', 'Recon successfully Edited')
      } else {
        showNotification('success', 'A new Recon is successfully added')
      }

      dispatchError(resetError({
        addReconStatus: ''
      }))
      if (defaultValues) {
        props.onGetReconDetail({
          reconId: defaultValues?.id
        })
      } else {
        props.onFetchReconList({})
      }
      props.onCloseReconForm()
    } else if (ADD_RECON_ERROR && addReconStatus) {
      showNotification('error', addReconStatus)
      dispatchError(resetError({
        addReconStatus: ''
      }))
    }
    if (GET_PROVIDER_LIST_ERROR && getProviderListStatus) {
      showNotification('error', getProviderListStatus)
      dispatchError(resetError({
        getProviderListStatus: ''
      }))
    }
  }, [addReconStatus, defaultValues, dispatchError,
    ADD_RECON_ERROR, props, GET_PROVIDER_LIST_ERROR,
    getProviderListStatus
  ])

  useEffect(() => {
    getProviderListRequest()
  }, [getProviderListRequest])

  const handleSubmit = useCallback((e) => {
    e.preventDefault()
    props.form.validateFields(async (err, values) => {
      if (!err) {
        let errTemp = {}
        let finalData = {
          provider: values.provider,
          purpose: values.purpose,
          recon_type: reconType,
          recon_to: reconTo,
          payment_date: moment(values.payment_date).format('YYYY-MM-DD'),
          amount: values.amount,
          remarks: values.remarks
        }
        if (!reconFile) {
          errTemp = {
            ...errTemp,
            recon_file: 'Please upload recon file'
          }
        }
        if (!invoiceFile) {
          errTemp = {
            ...errTemp,
            invoice_file: 'Please upload invoice file'
          }
        }
        if (!paymentProofFile) {
          errTemp = {
            ...errTemp,
            payment_proof: 'Please upload the payment proof'
          }
        }
        if (!isEmpty(errTemp)) {
          setErrorObj(errTemp)
          return
        }
        if (defaultValues?.id) {
          // sending these values only if they are updated
          if (reconFile !== defaultValues?.file_url) {
            finalData.file_url = reconFile
          }
          if (invoiceFile !== defaultValues?.invoice_file) {
            finalData.invoice_url = invoiceFile
          }
          if (paymentProofFile !== defaultValues?.payment_proof_url) {
            finalData.payment_proof_url = paymentProofFile
          }
        } else {
          finalData = {
            ...finalData,
            file_url: reconFile,
            invoice_url: invoiceFile,
            payment_proof_url: paymentProofFile
          }
        }
        addReconRequest({
          reconId: defaultValues?.id,
          body: finalData
        })
      }
    })
  }, [addReconRequest,
    defaultValues, props.form,
    reconType, reconTo, invoiceFile,
    reconFile, paymentProofFile
  ])

  const renderFormItems = useCallback((item) => {
    // wrapping utitily function with class function to pass common parameters
    return renderFormItemsUtil({
      ...item,
      getFieldDecorator: props.form.getFieldDecorator,
      getFieldValue: props.form.getFieldValue
    })
  }, [props.form])

  const renderForm = useCallback((formData) => {
    return (
      formData.map((item, index) => (
        renderFormItems(item)
      ))
    )
  }, [renderFormItems])

  const handleSaveNewUploadImg = useCallback((file, fileType) => {
    switch (fileType) {
      case 'payment_proof_file':
        setErrorObj({
          payment_proof_file: ''
        })
        setPaymentProofFile(file)
        break
      case 'invoice_file':
        setErrorObj({
          invoice_file: ''
        })
        setInvoiceFile(file)
        break
      case 'recon_file':
        setErrorObj({
          recon_file: ''
        })
        setReconFile(file)
        break
      default:
    }
  }, [])

  const handleRemoveImg = useCallback((fileType) => {
    switch (fileType) {
      case 'payment_proof_file':
        setPaymentProofFile('')
        break
      case 'invoice_file':
        setInvoiceFile('')
        break
      case 'recon_file':
        setReconFile('')
        break
      default:
    }
  }, [])

  const handleReconTypeChange = useCallback((e) => {
    setReconType(e.target.value)
    if (e.target.value === 'EXTRA_COMMISSION') {
      setReconTo('PPIB')
    }
  }, [])

  const handleReconToChange = useCallback((e) => {
    setReconTo(e.target.value)
  }, [])

  return (
    <ReconFormStyle>
      <Form onSubmit={handleSubmit}>
        {
          renderForm([
            {
              name: 'provider',
              title: 'Provider Name',
              type: 'search',
              data: getProviderListData,
              defaultValue: get(defaultValues, 'provider', '')
            },
            {
              name: 'purpose',
              title: 'Recon Purpose',
              type: 'search',
              data: [
                {
                  code: 'NEW',
                  name: 'New'
                },
                {
                  code: 'ENDORSEMENT',
                  name: 'Endorsement'
                }
              ],
              defaultValue: get(defaultValues, 'recon_purpose', '')
            }
          ])
        }
        <div>
          Recon Type
        </div>
        <div className='errorText'>{errorObj.recon_type}</div>
        <Radio.Group onChange={handleReconTypeChange} value={reconType}>
          <Radio value='OJK'>OJK Commission</Radio>
          <Radio value='EXTRA_COMMISSION'>Extra Commission</Radio>
        </Radio.Group>

        <div className='mt-20'>
          Recon To
        </div>
        <div className='errorText'>{errorObj.recon_to}</div>
        <Radio.Group onChange={handleReconToChange} value={reconTo}>
          <Radio value='PPIB'> PPIB </Radio>
          <Radio value='PROVIDER' disabled={reconType === 'EXTRA_COMMISSION'}> Provider </Radio>
        </Radio.Group>
        <div className='mt-20'>
          {
            renderForm([
              {
                name: 'payment_date',
                title: 'Payment Date',
                type: 'date',
                handleDisabledDate: (current) => (current > moment().endOf('day')),
                defaultValue: get(defaultValues, 'payment_date')
              }
            ])
          }
        </div>

        <div className='mt-20'>
          <span className='required-star'>*</span> Recon data (excel file based on the template)
        </div>
        <div className='errorText'>{errorObj.recon_file}</div>

        <UploadImgPreview
          onSave={(file) => handleSaveNewUploadImg(file, 'recon_file')}
          name='recon_file'
          img={reconFile}
          isNew={!reconFile}
          fileType='.xls,.xlsx'
          onRemove={() => handleRemoveImg('recon_file')}
        />

        <div className='mt-20'>
          <span className='required-star'>*</span> Invoice (PDF File)
        </div>
        <div className='errorText'>{errorObj.invoice_file}</div>

        <UploadImgPreview
          onSave={(file) => handleSaveNewUploadImg(file, 'invoice_file')}
          name='invoice_file'
          img={invoiceFile}
          isNew={!invoiceFile}
          fileType='.pdf'
          onRemove={() => handleRemoveImg('invoice_file')}
        />

        <div className='mt-20'>
          <span className='required-star'>*</span> Payment Proof (PDF/Image File)
        </div>
        <div className='errorText'>{errorObj.payment_proof}</div>

        <UploadImgPreview
          onSave={(file) => handleSaveNewUploadImg(file, 'payment_proof_file')}
          name='payment_proof_file'
          img={paymentProofFile}
          isNew={!paymentProofFile}
          fileType='.pdf,.png,.jpg,.jpeg'
          onRemove={() => handleRemoveImg('payment_proof_file')}
        />

        {
          renderForm([
            {
              name: 'amount',
              title: `Total Amount Should Be Paid To ${reconTo === 'PPIB' ? 'PPIB' : 'Provider'}`,
              type: 'number',
              min: 0,
              defaultValue: get(defaultValues, 'amount', 0)
            },
            {
              name: 'remarks',
              title: 'Remark',
              type: 'textarea',
              required: false,
              defaultValue: get(defaultValues, 'remarks', 0)
            }
          ])
        }
        <p>
          <i>
            Data rekon yang Anda upload langsung diproses setelah Anda klik tombol Submit.
            Pastikan semua informasi san data recon yang Anda masukkan sudah sesuai!
          </i>
        </p>
        <Row justify='end' type='flex'>
          <Button className='mt-20' type='primary' htmlType='submit'>
            Submit
          </Button>
        </Row>
      </Form>
    </ReconFormStyle>
  )
}

ReconForm.propTypes = {
  defaultValues: PropTypes.object,
  onGetReconDetail: PropTypes.func,
  onFetchReconList: PropTypes.func,
  onCloseReconForm: PropTypes.func
}

const wrapperReconForm = Form.create()(ReconForm)

export default wrapperReconForm
