import { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../state/reducer'

// this is the context used by the all pages
export const ReconContext = createContext()

// provider provide the update context value
export const ReconContextProvider = (props) => {
  // use reducer provides the initial state and dispatch function
  // to all nested children [state, dispatch]

  return (
    <ReconContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {props.children}
    </ReconContext.Provider>
  )
}

// use to read the value from the global state
export const useReconContextValue = () => useContext(ReconContext)
