import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { useReconContextValue } from '../../context'
import { getReconList, addRecon, getReconDetail, getPolicyList } from '../actions'

export const useReconServiceCall = (actionsCall = () => {}) => {
  const [providerState, dispatch] = useReconContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = useCallback(async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }, [callApi, actionsCall])

  return [providerState, request]
}

export const useGetPolicyList = () => useReconServiceCall(getPolicyList)
export const useGetReconList = () => useReconServiceCall(getReconList)
export const useGetReconDetail = () => useReconServiceCall(getReconDetail)
export const useAddRecon = () => useReconServiceCall(addRecon)
