import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback, useRef } from 'react'
import { useAgentContextValue } from '../../context'
import {
  getAddonsList, getProductAddons, uploadFile,
  getAddonPremium, updateAgentStore, getProviderList,
  getApplicationFilter, getPackageList
} from '../actions'

export const useAgentServiceCall = (actionsCall = () => {}) => {
  const [agentState, dispatch] = useAgentContextValue()
  const [callApi] = useServiceRequest(dispatch)
  const callApiRef = useRef(callApi)
  const request = useCallback(async (payload = {}) => {
    await callApiRef.current(actionsCall({
      ...payload
    }))
  }, [actionsCall])

  return [agentState, request]
}

export const useUpdateAgentStore = () => {
  const [, dispatch] = useAgentContextValue()
  return useCallback((data) => {
    dispatch(updateAgentStore(data))
  }, [dispatch])
}

export const useGetAddonsList = () => useAgentServiceCall(getProductAddons)

export const useGetAddons = () => useAgentServiceCall(getAddonsList)

export const useGetAddonsPremium = () => useAgentServiceCall(getAddonPremium)

export const useUploadFile = () => useAgentServiceCall(uploadFile)

export const useGetProviderList = () => useAgentServiceCall(getProviderList)

export const useApplicationFilter = () => useAgentServiceCall(getApplicationFilter)

export const useGetPackageList = () => useAgentServiceCall(getPackageList)
